// The agent adds [[HANDOFF]] when it could not help on its own.
// Strip the token before the customer sees it, and raise the flag for the owner.
const raw = String($json.output || '');
const needsHuman = /\[\[HANDOFF\]\]/.test(raw);
const reply = raw.replace(/\[\[HANDOFF\]\]/g, '').trim();
const chatId = $('Message arrives').item.json.message.chat.id;
const asked = String($('Message arrives').item.json.message.text || '').slice(0, 140);

return [{
  json: {
    reply: reply || 'Sorry, could you write that again, please?',
    needs_human: needsHuman,
    chat_id: chatId,
    owner_chat_id: $('Your settings').item.json.owner_chat_id,
    owner_text: needsHuman ? `A customer needs you. They wrote: "${asked}"` : ''
  }
}];
